const express = require("express");
const app = express();

app.get("/", (req, res) => res.send("Trang chủ"));

app.get("/hello/:name", (req, res) => {
  res.json({ message: "Xin chào " + req.params.name });
});

app.get("/search", (req, res) => {
  // /search?q=node  ->  req.query.q === "node"
  res.json({ q: req.query.q });
});

// app.listen(3000) ngoài máy thật. Ở đây dùng inject:
(async () => {
  for (const url of ["/", "/hello/Lexi", "/search?q=node"]) {
    const r = await app.inject(url);
    console.log(r.statusCode, r.body);
  }
})();

