const express = require("express");
const app = express();

app.get("/greet", (req, res) => {
  const name = req.query.name || "stranger";
  res.send("Hello, " + name);
});

(async () => {
  console.log((await app.inject("/greet?name=Lexi")).body);
  console.log((await app.inject("/greet")).body);
})();
